function Donut({items,total,selectedName,hoveredName,onSelect,onHover}){let offset=0;const circumference=2*Math.PI*74,activeName=hoveredName||selectedName,active=items.find(item=>item.name===activeName);return <div className="donut-wrap"><svg viewBox="0 0 180 180" className="donut" role="group" aria-label="Gastos por categoría"><circle cx="90" cy="90" r="74" fill="none" stroke="#eef0ec" strokeWidth="20"/>{items.map(item=>{const length=total?item.amount/total*circumference:0,midpoint=((offset+length/2)/circumference)*2*Math.PI,raised=item.name===activeName,dx=raised?Math.cos(midpoint)*7:0,dy=raised?Math.sin(midpoint)*7:0;const node=<circle key={item.name} className={`donut-slice${raised?' selected':''}`} role="button" tabIndex="0" aria-label={`${item.name}: ${money(item.amount)}, ${Math.round(item.amount/total*100)}%`} aria-pressed={item.name===selectedName} onMouseEnter={()=>onHover(item.name)} onMouseLeave={()=>onHover('')} onFocus={()=>onHover(item.name)} onBlur={()=>onHover('')} onClick={()=>onSelect(item.name===selectedName?'':item.name)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();onSelect(item.name===selectedName?'':item.name)}}} title={`${item.name}: ${money(item.amount)}`} cx="90" cy="90" r="74" fill="none" stroke={item.color} strokeWidth={raised?23:20} strokeDasharray={`${length} ${circumference-length}`} strokeDashoffset={-offset} strokeLinecap="round" style={{transform:`translate(${dx}px, ${dy}px)`}}/>;offset+=length+3;return node})}</svg><div className={`donut-center${active?' has-selection':''}`} aria-live="polite"><span>{active?.name||'Gasto total'}</span><strong>{money(active?.amount??total)}</strong><small>{active?`${Math.round(active.amount/total*100)}% del mes`:'este mes'}</small></div></div>}
